//! Dependency guards for patches that keep their own index or cache next to BYOND's data ([`Dep`] tables in
//! [`Config::deps`](crate::driver::Config::deps), generated by `tools/depsig.py`). Signatures don't prove the rest
//! of BYOND still treats the mirrored data the same way, so before any patch writes code, a patch failing one of
//! these checks is not installed:
//!
//! - Fingerprint: each function the patch replaces, or that writes its data, matches a known form.
//! - Globals: the writable globals such a function uses have the known number of code references (relocations).
//! - Callers: unhooked writers have the known number of `call` sites.
//!
//! A new BYOND build that changes any of this disables the patch until accepted (`depsig.py --accept`).

use std::sync::Mutex;

use rustc_hash::FxHashMap;

use crate::image::Image;

/// A [`Variant::globals`] offset for a global that form doesn't address.
const ABSENT: u16 = 0xFFFF;

/// One known form of a function: its IDA-style signature and the offset of each [`Dep::globals`] operand in it.
pub struct Variant {
    pub ida: &'static str,
    pub globals: &'static [u16],
}

/// A function some patches depend on: its forms and accepted reference and call site counts (empty `callers`:
/// not checked). Its name is the comment above it.
pub struct Dep {
    pub keys: &'static [&'static str],
    pub globals: &'static [&'static [u32]],
    pub callers: &'static [u32],
    pub variants: &'static [Variant],
}

static MISSING: Mutex<Vec<&'static str>> = Mutex::new(Vec::new());

/// Check `deps` (this platform's) against `core` before any patch is installed.
pub(crate) fn check(deps: &[Dep], core: &Image) {
    // Images are open while deps are checked (before install); a closed one finds nothing, as if every dep failed.
    let code = core.hays(Some(true)).unwrap_or_default();

    // Fingerprints: the first form that occurs exactly once (all forms searched in one pass).
    let pats: Vec<Vec<Option<u8>>> =
        deps.iter().flat_map(|d| d.variants).map(|v| crate::scan::parse(v.ida).unwrap_or_default()).collect();
    let mut hits = crate::scan::find_patterns(&code, &pats).into_iter();
    let found: Vec<Option<(usize, &Variant)>> = deps
        .iter()
        .map(|dep| {
            let mut first = None;
            for v in dep.variants {
                // Every form's hits are consumed, matched or not, to stay in step with `pats`.
                let h = hits.next().unwrap_or_default();
                if first.is_none()
                    && let [at] = h[..]
                {
                    first = Some((at, v));
                }
            }
            first
        })
        .collect();

    // Globals: count code references (relocated words in code) to each matched form's globals.
    let present = |v: &'static Variant| v.globals.iter().enumerate().filter(|&(_, &off)| off != ABSENT);
    let global = |at: usize, off: u16| core.u32_at(at + off as usize).ok();
    let mut refs: FxHashMap<u32, u32> = FxHashMap::default();
    for (at, v) in found.iter().flatten() {
        for (_, &off) in present(v) {
            if let Some(g) = global(*at, off) {
                refs.insert(g, 0);
            }
        }
    }
    let code_ranges = core.code_ranges();
    let in_code = |a: usize| code_ranges.iter().any(|&(s, n)| s <= a && a + 4 <= s + n);
    for site in core.reloc_sites() {
        if in_code(site)
            && let Ok(word) = core.u32_at(site)
            && let Some(n) = refs.get_mut(&word)
        {
            *n += 1;
        }
    }

    // Callers: `call rel32` sites targeting each checked function.
    let mut calls: FxHashMap<usize, u32> = FxHashMap::default();
    for (dep, f) in deps.iter().zip(&found) {
        if let Some((at, _)) = f
            && !dep.callers.is_empty()
        {
            calls.insert(*at, 0);
        }
    }
    if !calls.is_empty() {
        for &(start, bytes) in &code {
            for i in memchr::memchr_iter(0xE8, &bytes[..bytes.len().saturating_sub(4)]) {
                let rel = i32::from_le_bytes([bytes[i + 1], bytes[i + 2], bytes[i + 3], bytes[i + 4]]);
                if let Some(n) = calls.get_mut(&(start + i + 5).wrapping_add(rel as usize)) {
                    *n += 1;
                }
            }
        }
    }

    let mut missing = crate::sync::lock(&MISSING);
    missing.clear();
    for (dep, f) in deps.iter().zip(&found) {
        let ok = f.is_some_and(|(at, v)| {
            let globals_ok = present(v).all(|(g, &off)| {
                global(at, off).and_then(|w| refs.get(&w)).is_some_and(|n| dep.globals[g].contains(n))
            });
            globals_ok && (dep.callers.is_empty() || calls.get(&at).is_some_and(|n| dep.callers.contains(n)))
        });
        if !ok {
            for &k in dep.keys {
                if !missing.contains(&k) {
                    missing.push(k);
                }
            }
        }
    }
}

pub(crate) fn missing(key: &str) -> bool {
    crate::sync::lock(&MISSING).contains(&key)
}
